import { Registry, } from "./core.js";
export * from "./core.js";
export * as Plugin from "./plugin.js";
/**
 * The registry of native app menu items, contributed from main entries. Windows without a native menubar show them
 * in the in-app menu.
 *
 * @example
 * ```ts
 * ctx.add(MenubarItem, {
 *   menu: "help",
 *   id: "check",
 *   get label() {
 *     return ctx.t("menu.check")
 *   },
 *   run: () => void check(),
 * })
 * ```
 */
export const MenubarItem = Registry.define("menubar-item");
